package com.gathin.tvhome;
import android.app.*;import android.content.*;import android.os.*;import android.provider.Settings;import android.text.InputType;import android.widget.*;import java.util.*;

/** Local settings UI backed by an explicitly ADB-started, signed-client-only session. */
final class SessionSettingsUi {
 static boolean starterAvailable(Context c){return c.getPackageManager().checkSignatures(c.getPackageName(),"local.hy320.helperstarter")==android.content.pm.PackageManager.SIGNATURE_MATCH;}
 static void openStarter(Activity a){if(!starterAvailable(a)){unavailable(a);return;}try{a.startActivity(new Intent().setComponent(new ComponentName("local.hy320.helperstarter","local.hy320.helperstarter.MainActivity")));}catch(android.content.ActivityNotFoundException missing){Toast.makeText(a,"Settings Starter is unavailable.",Toast.LENGTH_LONG).show();}}
 static void unavailable(Activity a){Toast.makeText(a,starterAvailable(a)?"Open Settings Starter in Other settings to start the helper.":"Connect the ADB settings helper from your computer first.",Toast.LENGTH_LONG).show();}
 static boolean ready(Activity a){if(SettingsSessionClient.connected())return true;unavailable(a);return false;}
 interface Result {void done(Bundle result)throws Exception;}
 static void read(Activity a,int code,Bundle input,Result result){new Thread(()->{try{Bundle response=SettingsSessionClient.call(code,input);a.runOnUiThread(()->{if(!a.isFinishing()&&!a.isDestroyed())try{result.done(response);}catch(Exception failure){error(a,failure);}});}catch(Exception failure){a.runOnUiThread(()->error(a,failure));}},"settings-session-read").start();}
 static void error(Activity a,Exception failure){if(!a.isFinishing()&&!a.isDestroyed())Toast.makeText(a,failure.getMessage()==null?"Operation was not confirmed.":failure.getMessage(),Toast.LENGTH_LONG).show();}
 static void change(Activity a,int code,Bundle input,Runnable refresh){if(!ready(a))return;new Thread(()->{try{
   if(code==SettingsSessionClient.STOP)a.sendBroadcast(new Intent("com.gathin.tvhome.SETTINGS_STARTER_STOPPED").setComponent(new ComponentName("local.hy320.helperstarter","local.hy320.helperstarter.ReadyReceiver")),"com.gathin.tvhome.permission.SETTINGS_STARTER");
   remember(a,code,input);Bundle result=SettingsSessionClient.call(code,input);
   if(code==SettingsSessionClient.SESSION_MODE&&!a.getSharedPreferences("settings_helper_policy",0).edit().putBoolean("until_debug_off",input.getBoolean("until_debug_off")).commit())throw new IllegalStateException("Session changed, but its restart preference could not be saved.");
   if(!a.getSharedPreferences("settings_session_receipt",0).edit().putInt("operation",code).putBoolean("success",true).putLong("at",System.currentTimeMillis()).putString("package",input.getString("package")).commit())throw new IllegalStateException("Change completed, but its receipt could not be saved. Check state before retrying.");
   a.runOnUiThread(()->{if(!a.isFinishing()&&!a.isDestroyed()){if(code==SettingsSessionClient.ZONE)TimeZone.setDefault(null);Toast.makeText(a,result.getBoolean("requested")?"Request sent. Check the current status.":"Saved",Toast.LENGTH_SHORT).show();refresh.run();}});
  }catch(Exception failure){if(code==SettingsSessionClient.CACHE)a.getSharedPreferences("settings_session_receipt",0).edit().putString("cache_error",failure.getMessage()).commit();a.getSharedPreferences("settings_session_receipt",0).edit().putInt("operation",code).putBoolean("success",false).putLong("at",System.currentTimeMillis()).putString("package",input.getString("package")).commit();a.runOnUiThread(()->error(a,failure));}},"settings-session-change").start();}
 private static synchronized void remember(Activity a,int code,Bundle input)throws Exception{
  SharedPreferences p=a.getSharedPreferences("settings_session_undo",0);String key=null;Bundle before=null;
  if(code==SettingsSessionClient.SESSION_MODE&&!p.getBoolean("helper_mode.recorded",false)){SharedPreferences old=a.getSharedPreferences("settings_helper_policy",0);if(!p.edit().putBoolean("helper_mode.recorded",true).putBoolean("helper_mode.present",old.contains("until_debug_off")).putBoolean("helper_mode",old.getBoolean("until_debug_off",false)).commit())throw new IllegalStateException("Could not record the original session mode.");}
  if(code==SettingsSessionClient.HOTSPOT_SET||code==SettingsSessionClient.HOTSPOT_POWER)SettingsSessionSecrets.capture(a,SettingsSessionClient.call(SettingsSessionClient.HOTSPOT_READ,new Bundle()));
  if(code==SettingsSessionClient.DEVICE&&"rename".equals(input.getString("action"))){Bundle list=SettingsSessionClient.call(SettingsSessionClient.BONDED,new Bundle());ArrayList<Bundle> devices=list.getParcelableArrayList("devices");Bundle original=null;if(devices!=null)for(Bundle device:devices)if(device.getString("address").equals(input.getString("address"))){original=new Bundle();original.putString("address",device.getString("address"));original.putString("alias",device.getString("alias"));}if(original==null)throw new IllegalStateException("Paired device unavailable");SettingsSessionSecrets.capture(a,"bluetooth_alias."+input.getString("address"),original);}
  if(code==SettingsSessionClient.ETHERNET_SET){Bundle original=new Bundle();original.putString("interface",input.getString("interface"));original.putParcelable("config",input.getParcelable("config"));SettingsSessionSecrets.capture(a,"ethernet."+input.getString("interface"),original);}
  if(code==SettingsSessionClient.WIFI||code==SettingsSessionClient.BLUETOOTH||code==SettingsSessionClient.ZONE||code==SettingsSessionClient.TIME||code==SettingsSessionClient.TIMER){key=code==2?"wifi":code==3?"bluetooth":code==5?"zone":code==4?"time":"timer";before=SettingsSessionClient.call(SettingsSessionClient.STATUS,new Bundle());}
  if(key!=null&&!p.getBoolean(key+".recorded",false)){
   SharedPreferences.Editor edit=p.edit().putBoolean(key+".recorded",true);
   if(code==SettingsSessionClient.WIFI){int state=before.getInt("wifi");if(state!=1&&state!=3)throw new IllegalStateException("Wi-Fi is changing. Wait for it to finish.");edit.putBoolean(key,state==3);}
   else if(code==SettingsSessionClient.BLUETOOTH){int state=before.getInt("bluetooth");if(state!=10&&state!=12)throw new IllegalStateException("Bluetooth is changing. Wait for it to finish.");edit.putBoolean(key,state==12);}
   else if(code==SettingsSessionClient.ZONE)edit.putString(key,before.getString("zone"));
   else if(code==SettingsSessionClient.TIME)edit.putLong(key,System.currentTimeMillis()).putLong("time.elapsed",SystemClock.elapsedRealtime()).putInt("time.boot",Settings.Global.getInt(a.getContentResolver(),"boot_count",-1));
   else edit.putLong(key,before.getLong("timer"));
   if(!edit.commit())throw new IllegalStateException("Could not preserve the original setting.");
  }
  if(code==SettingsSessionClient.SET_PERMISSION){Bundle old=SettingsSessionClient.call(SettingsSessionClient.PERMISSION,input);ArrayList<Bundle> records=old.getParcelableArrayList("permissions");SharedPreferences.Editor editor=p.edit();if(records!=null)for(Bundle record:records){String id="permission."+input.getString("package")+"|"+record.getString("permission");if(!p.contains(id))editor.putBoolean(id,record.getBoolean("granted")).putInt(id+".flags",record.getInt("flags"));}if(!editor.commit())throw new IllegalStateException("Could not preserve the permission state.");}
 }
 static Bundle originals(Context context){Bundle out=new Bundle();SharedPreferences p=context.getSharedPreferences("settings_session_undo",0);for(java.util.Map.Entry<String,?> entry:p.getAll().entrySet()){Object v=entry.getValue();if(v instanceof String)out.putString(entry.getKey(),(String)v);else if(v instanceof Boolean)out.putBoolean(entry.getKey(),(Boolean)v);else if(v instanceof Long)out.putLong(entry.getKey(),(Long)v);else if(v instanceof Integer)out.putInt(entry.getKey(),(Integer)v);}return out;}
 static Bundle restore(Context context,String key)throws Exception{
  SharedPreferences p=context.getSharedPreferences("settings_session_undo",0);Bundle b=new Bundle();int code;
  if("wifi".equals(key)||"bluetooth".equals(key)){if(!p.getBoolean(key+".recorded",false))throw new IllegalStateException("No original recorded");b.putBoolean("on",p.getBoolean(key,false));code="wifi".equals(key)?SettingsSessionClient.WIFI:SettingsSessionClient.BLUETOOTH;}
  else if("zone".equals(key)){if(!p.getBoolean("zone.recorded",false))throw new IllegalStateException("No original recorded");b.putString("zone",p.getString("zone",null));code=SettingsSessionClient.ZONE;}
  else if("time".equals(key)){if(!p.getBoolean("time.recorded",false)||p.getInt("time.boot",-1)!=Settings.Global.getInt(context.getContentResolver(),"boot_count",-2))throw new IllegalStateException("Original clock belongs to another boot or is absent");long elapsed=SystemClock.elapsedRealtime()-p.getLong("time.elapsed",Long.MAX_VALUE);if(elapsed<0)throw new IllegalStateException("Clock elapsed time is invalid");b.putLong("time",p.getLong("time",0)+elapsed);code=SettingsSessionClient.TIME;}
  else if("timer".equals(key)){if(!p.getBoolean("timer.recorded",false)||p.getLong("timer",-1)!=0)throw new IllegalStateException("No original Off timer recorded");b.putInt("seconds",0);code=SettingsSessionClient.TIMER;}
  else if("helper_mode".equals(key)){if(!p.getBoolean("helper_mode.recorded",false))throw new IllegalStateException("No original session mode recorded");b.putBoolean("until_debug_off",p.getBoolean("helper_mode",false));Bundle result=SettingsSessionClient.call(SettingsSessionClient.SESSION_MODE,b);SharedPreferences.Editor edit=context.getSharedPreferences("settings_helper_policy",0).edit();if(p.getBoolean("helper_mode.present",false))edit.putBoolean("until_debug_off",p.getBoolean("helper_mode",false));else edit.remove("until_debug_off");if(!edit.commit())throw new IllegalStateException("Could not restore session preference");return result;}
  else if(key!=null&&key.startsWith("bluetooth_alias.")){b=SettingsSessionSecrets.original(context,key);b.putString("action","restore_alias");code=SettingsSessionClient.DEVICE;}
  else if(key!=null&&key.startsWith("ethernet.")){b=SettingsSessionSecrets.original(context,key);code=SettingsSessionClient.ETHERNET_RESTORE;}
  else if("hotspot".equals(key)){b=SettingsSessionSecrets.original(context);code=SettingsSessionClient.HOTSPOT_RESTORE;}
  else if("hotspot_power".equals(key)){b.putBoolean("on",SettingsSessionSecrets.original(context).getInt("state")==13);code=SettingsSessionClient.HOTSPOT_POWER;}
  else if(key!=null&&key.startsWith("permission.")&&p.contains(key)){String[] id=SettingsSessionPolicy.permissionRecord(key);b.putString("package",id[0]);b.putString("permission",id[1]);b.putBoolean("granted",p.getBoolean(key,false));b.putInt("flags",p.getInt(key+".flags",0));code=SettingsSessionClient.RESTORE_PERMISSION;}
  else throw new IllegalArgumentException("Unknown original setting");
  return SettingsSessionClient.call(code,b);
 }
 static void power(Activity a,boolean bluetooth,Runnable refresh){if(!ready(a))return;read(a,SettingsSessionClient.STATUS,new Bundle(),state->{
  boolean on=bluetooth?state.getInt("bluetooth")==12:state.getInt("wifi")==3;final int[] target={on?1:0};
  CheckBox alternate=new CheckBox(a);alternate.setText("I have a working IR remote or USB input device");alternate.setTextColor(0xfff5f5fa);
  AlertDialog.Builder builder=new SettingsPopup.Builder(a).setTitle(bluetooth?"Bluetooth":"Wi-Fi").setSingleChoiceItems(new String[]{"Off","On"},target[0],(d,w)->target[0]=w);
  if(bluetooth)builder.setView(alternate);
  AlertDialog dialog=builder.setPositiveButton("Apply",null).setNegativeButton("Cancel",null).create();dialog.show();SettingsPopup.style(dialog);
  dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{if((target[0]==1)==on){dialog.dismiss();return;}if(bluetooth&&target[0]==0&&!alternate.isChecked()){Toast.makeText(a,"Confirm alternate control before disabling Bluetooth.",Toast.LENGTH_LONG).show();return;}
   Runnable apply=()->{Bundle b=new Bundle();b.putBoolean("on",target[0]==1);b.putBoolean("backup_control",alternate.isChecked());dialog.dismiss();change(a,bluetooth?SettingsSessionClient.BLUETOOTH:SettingsSessionClient.WIFI,b,refresh);};
   if(!bluetooth&&target[0]==0)confirm(a,"Turn Wi-Fi off?","This disconnects the computer and may stop the helper. Keep access to the stock Wi-Fi screen to reconnect.",apply);else apply.run();
  });
 });}
 static void confirm(Activity a,String title,String message,Runnable action){AlertDialog d=new SettingsPopup.Builder(a).setTitle(title).setMessage(message).setPositiveButton("Confirm",(dialog,w)->action.run()).setNegativeButton("Cancel",null).create();d.show();SettingsPopup.style(d);d.getButton(AlertDialog.BUTTON_NEGATIVE).requestFocus();}
 static void clock(Activity a,String kind,Runnable refresh){if(!ready(a))return;
  if(!"Time zone".equals(kind)&&Settings.Global.getInt(a.getContentResolver(),"auto_time",0)!=0){Toast.makeText(a,"Turn off Auto time first.",Toast.LENGTH_LONG).show();return;}
  if("Time zone".equals(kind)){
   if(Settings.Global.getInt(a.getContentResolver(),"auto_time_zone",0)!=0){Toast.makeText(a,"Turn off Automatic time zone first.",Toast.LENGTH_LONG).show();return;}
   String[] ids=TimeZone.getAvailableIDs();Arrays.sort(ids);int current=Arrays.asList(ids).indexOf(TimeZone.getDefault().getID());final int[] selected={current};
   AlertDialog d=new SettingsPopup.Builder(a).setTitle("Time zone").setSingleChoiceItems(ids,current,(dialog,w)->selected[0]=w).setPositiveButton("Apply",(dialog,w)->{if(selected[0]>=0)change(a,SettingsSessionClient.ZONE,SettingsSessionClient.input("zone",ids[selected[0]]),refresh);}).setNegativeButton("Cancel",null).create();d.show();SettingsPopup.style(d);return;
  }
  Calendar now=Calendar.getInstance();boolean date="Date".equals(kind);DatePicker day=new DatePicker(a);day.init(now.get(Calendar.YEAR),now.get(Calendar.MONTH),now.get(Calendar.DAY_OF_MONTH),null);TimePicker time=new TimePicker(a);time.setIs24HourView(android.text.format.DateFormat.is24HourFormat(a));time.setHour(now.get(Calendar.HOUR_OF_DAY));time.setMinute(now.get(Calendar.MINUTE));
  AlertDialog d=new SettingsPopup.Builder(a).setTitle(kind).setView(date?day:time).setPositiveButton("Apply",(dialog,w)->{try{Calendar target=Calendar.getInstance();target.setLenient(false);if(date)target.set(day.getYear(),day.getMonth(),day.getDayOfMonth());else{target.set(Calendar.HOUR_OF_DAY,time.getHour());target.set(Calendar.MINUTE,time.getMinute());target.set(Calendar.SECOND,0);}Bundle b=new Bundle();b.putLong("time",target.getTimeInMillis());SettingsSessionPolicy.timestamp(target.getTimeInMillis());change(a,SettingsSessionClient.TIME,b,refresh);}catch(RuntimeException invalid){Toast.makeText(a,"Choose a valid date and time.",Toast.LENGTH_LONG).show();}}).setNegativeButton("Cancel",null).create();d.show();SettingsPopup.style(d);
 }
 static void network(Activity a,String wanted,Runnable refresh){if(!ready(a))return;read(a,SettingsSessionClient.NETWORKS,new Bundle(),result->{
  ArrayList<Bundle> items=result.getParcelableArrayList("networks");if(items==null)items=new ArrayList<>();ArrayList<Bundle> selected=new ArrayList<>();for(Bundle item:items)if(wanted==null||wanted.equals(item.getString("name")))selected.add(item);
  if(selected.isEmpty()){addNetwork(a,wanted,refresh);return;}
  String[] labels=new String[selected.size()];for(int i=0;i<labels.length;i++)labels[i]=selected.get(i).getString("name")+(selected.get(i).getBoolean("current")?" (connected)":"");
  AlertDialog d=new SettingsPopup.Builder(a).setTitle("Saved networks").setItems(labels,(dialog,w)->networkActions(a,selected.get(w),refresh)).setPositiveButton("Add network",(dialog,w)->addNetwork(a,null,refresh)).setNegativeButton("Close",null).create();d.show();SettingsPopup.style(d);
 });}
 private static void networkActions(Activity a,Bundle item,Runnable refresh){String name=item.getString("name");AlertDialog d=new SettingsPopup.Builder(a).setTitle(name).setItems(new String[]{"Connect","Forget network"},(dialog,w)->{
  Bundle input=new Bundle();input.putInt("id",item.getInt("id"));input.putString("name",name);confirm(a,w==0?"Connect to this network?":"Forget this network?",w==0?"Switching networks can disconnect the computer.":"Saved credentials will be removed. You may need the password to reconnect.",()->change(a,w==0?SettingsSessionClient.CONNECT:SettingsSessionClient.FORGET,input,refresh));
 }).setNegativeButton("Cancel",null).create();d.show();SettingsPopup.style(d);}
 static void addNetwork(Activity a,String name,Runnable refresh){SessionWifiUi.show(a,name,refresh);}
 static void appAction(Activity a,String pkg,int action,Runnable refresh){if(action==SettingsSessionClient.CACHE){AlertDialog d=new SettingsPopup.Builder(a).setTitle("Clear cache").setMessage("This firmware refuses cache-only clearing for the ADB helper. App data is left unchanged.").setPositiveButton("Close",null).create();d.show();SettingsPopup.style(d);return;}if(!ready(a))return;String title=action==SettingsSessionClient.CACHE?"Clear cache?":action==SettingsSessionClient.DATA?"Clear app data?":"Force stop app?";String message=action==SettingsSessionClient.DATA?"This permanently removes this app's accounts, preferences and saved data. There is no undo.":action==SettingsSessionClient.CACHE?"Delete temporary files for this app. Its accounts and settings are kept.":"Stop this app until it is opened or Android starts it again.";confirm(a,title,message,()->change(a,action,SettingsSessionClient.input("package",pkg),refresh));}
 static void permission(Activity a,String pkg,String name,String label,Runnable refresh){if(!ready(a))return;Bundle input=SettingsSessionClient.input("package",pkg);input.putString("permission",name);read(a,SettingsSessionClient.PERMISSION,input,result->{if(!result.getBoolean("editable")){Toast.makeText(a,"This permission is managed by Android.",Toast.LENGTH_LONG).show();return;}boolean granted=result.getBoolean("granted");confirm(a,(granted?"Revoke ":"Allow ")+label+"?","Change this app's access to this permission.",()->{input.putBoolean("granted",!granted);change(a,SettingsSessionClient.SET_PERMISSION,input,refresh);});});}
 static void timer(Activity a){if(!ready(a))return;read(a,SettingsSessionClient.STATUS,new Bundle(),state->{int[] seconds={0,300,600,1200,3600};String[] labels={"Off","5 minutes","10 minutes","20 minutes","1 hour"};int active=0;for(int i=1;i<seconds.length;i++)if(state.getLong("timer")>0&&state.getLong("timer")<=seconds[i]){active=i;break;}final int[] choice={active};AlertDialog d=new SettingsPopup.Builder(a).setTitle("Timed shutdown").setSingleChoiceItems(labels,active,(dialog,w)->choice[0]=w).setPositiveButton("Apply",(dialog,w)->{Bundle b=new Bundle();b.putInt("seconds",seconds[choice[0]]);if(choice[0]==0)change(a,SettingsSessionClient.TIMER,b,()->{});else confirm(a,"Schedule shutdown?","The projector will shut down normally after "+labels[choice[0]]+". Stopping the ADB helper cancels the timer.",()->change(a,SettingsSessionClient.TIMER,b,()->{}));}).setNegativeButton("Cancel",null).create();d.show();SettingsPopup.style(d);});}
 static void helper(Activity a){if(!ready(a))return;read(a,SettingsSessionClient.STATUS,new Bundle(),state->{LinearLayout box=new LinearLayout(a);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(28,12,28,12);RadioGroup group=new RadioGroup(a);String[] modes={"Expire after 2 hours",state.getBoolean("independent_of_debugging")?"Until reboot or Stop helper":"Until Wireless debugging is turned off"};int[] ids={android.view.View.generateViewId(),android.view.View.generateViewId()};for(int i=0;i<modes.length;i++){RadioButton button=new RadioButton(a);button.setId(ids[i]);button.setText(modes[i]);button.setTextColor(0xfff5f5fa);button.setTextSize(18);button.setPadding(4,8,4,8);group.addView(button);}group.check(ids[state.getBoolean("until_debug_off")?1:0]);box.addView(group);TextView note=new TextView(a);note.setText(state.getBoolean("independent_of_debugging")?"This locally started session works with Wireless debugging off. Reboot, launcher process exit or Stop helper ends it. Automatic startup is controlled in Settings Starter.":"Reboot, launcher process exit or Stop helper ends this computer-started session. Stopping the helper cancels its shutdown timer.");note.setTextColor(0xffd5dbe2);note.setTextSize(17);note.setPadding(8,18,8,8);box.addView(note);AlertDialog d=new SettingsPopup.Builder(a).setTitle("ADB settings helper").setView(box).setPositiveButton("Apply",(dialog,w)->{Bundle input=new Bundle();input.putBoolean("until_debug_off",group.getCheckedRadioButtonId()==ids[1]);change(a,SettingsSessionClient.SESSION_MODE,input,()->{});}).setNegativeButton("Cancel",null).setNeutralButton("Stop helper",(dialog,w)->change(a,SettingsSessionClient.STOP,new Bundle(),()->{})).create();d.show();SettingsPopup.style(d);});}
 private SessionSettingsUi(){}
}
